  check_cuda_tensor(arg_x_sc_t, "x_sc_t");
  check_dtype(arg_x_sc_t, DLDataType{kDLUInt, 8, 1}, "x_sc_t");
  TVM_FFI_CHECK(arg_col_blocks >= -2147483648LL && arg_col_blocks <= 2147483647LL, ValueError)
      << "scalar 'col_blocks' value " << arg_col_blocks
      << " is outside i32 range [-2147483648, 2147483647]";
  TVM_FFI_CHECK(arg_row_blocks >= -2147483648LL && arg_row_blocks <= 2147483647LL, ValueError)
      << "scalar 'row_blocks' value " << arg_row_blocks
      << " is outside i32 range [-2147483648, 2147483647]";
  check_same_device(arg_x_fp8, arg_x_bf16, "x_fp8", "x_bf16");
  check_same_device(arg_x_fp8_t, arg_x_bf16, "x_fp8_t", "x_bf16");
  check_same_device(arg_x_sc, arg_x_bf16, "x_sc", "x_bf16");
  check_same_device(arg_x_sc_t, arg_x_bf16, "x_sc_t", "x_bf16");
  TVM_FFI_CHECK(grid_x > 0 && grid_y > 0 && grid_z > 0, ValueError)
      << "launch grid dimensions must be positive, got (" << grid_x << ", " << grid_y
      << ", " << grid_z << ")";

  cudaStream_t stream = (cudaStream_t)TVMFFIEnvGetStream(dev.device_type, dev.device_id);
  CUtensorMap p_x_bf16 = EncodeTma_x_bf16(arg_x_bf16);
  CUtensorMap p_x_fp8 = EncodeTma_x_fp8(arg_x_fp8);
  CUtensorMap p_x_fp8_t = EncodeTma_x_fp8_t(arg_x_fp8_t);
  CUtensorMap p_x_sc = EncodeTma_x_sc(arg_x_sc);
  CUtensorMap p_x_sc_t = EncodeTma_x_sc_t(arg_x_sc_t);
  int32_t v_col_blocks = (int32_t)arg_col_blocks;
  int32_t v_row_blocks = (int32_t)arg_row_blocks;
  void* kargs[] = {&p_x_bf16, &p_x_fp8, &p_x_fp8_t, &p_x_sc, &p_x_sc_t, &v_col_blocks, &v_row_blocks};

  static const bool smem_ready = CakeSetMaxDynamicSmem(
      reinterpret_cast<const void*>(kernel_cake_mok_quantize_normal), 51200);
  (void)smem_ready;
  dim3 grid((uint32_t)grid_x, (uint32_t)grid_y, (uint32_t)grid_z);
  dim3 block(128u, 1u, 1u);

  cudaError_t launch_status = cudaLaunchKernel(
      reinterpret_cast<const void*>(kernel_cake_mok_quantize_normal), grid, block, kargs, 51200u, stream);
  TVM_FFI_CHECK(launch_status == cudaSuccess, RuntimeError)
      << "cudaLaunchKernel for kernel_cake_mok_quantize_normal failed: "
      << cudaGetErrorString(launch_status);
}

